def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay settings on default mode=fast, level=3; return values for mode, level, then extra keys."""
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=False):
        merged[k] = v
    return list(merged.values())


def test_settings_empty() -> None:
    assert settings([], []) == ["fast", "3"]


def test_settings_override_mode() -> None:
    assert settings(["mode"], ["safe"]) == ["safe", "3"]


def test_settings_override_level() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_settings_override_both_in_reverse_input_order() -> None:
    assert settings(["level", "mode"], ["1", "turbo"]) == ["turbo", "1"]


def test_settings_extra_keys() -> None:
    assert settings(["retries", "timeout"], ["5", "30"]) == [
        "fast",
        "3",
        "5",
        "30",
    ]


def test_settings_duplicate_keys_last_wins() -> None:
    assert settings(["mode", "mode"], ["eco", "sport"]) == ["sport", "3"]
    assert settings(["retries", "retries"], ["1", "2"]) == ["fast", "3", "2"]


def test_settings_mix_override_and_extras() -> None:
    keys = ["threads", "mode", "verbose", "level"]
    values = ["8", "silent", "true", "0"]
    assert settings(keys, values) == ["silent", "0", "8", "true"]

